function [first, capped, fin, nn, k, z] = nonfinite(x, y, n)
%NONFINITE  Values that are not finite: inf and nan take any unit, as a bare 0 does; isnan and isfinite test them.
%   x: real[s] (passed in s)
%   y: real[1] (passed a plain number)
%   n: int (passed a whole number)
%   returns first: real[s] (passed in s)
%   returns capped: real[s] (passed in s)
%   returns fin: bool (passed true or false)
%   returns nn: bool (passed true or false)
%   returns k: int (passed a whole number)
%   returns z: real[s] (passed in s)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    first = 0;
    capped = 0;
    fin = false;
    nn = false;
    k = 0;
    z = 0;
    t = Inf;
    if (x < 0)
        t = (-(Inf));
    end
    first = asils.pc.fmin(x, (Inf * 1));
    capped = asils.pc.clamp(x, (-(Inf)), 2);
    fin = (isfinite(t) || isfinite((y / n)));
    q = ((y - y) / (y - y));
    nn = ((isnan(q) && (~isnan(y))) && (~isnan(n)));
    k = asils.pc.choose(isfinite(t), 1, asils.pc.choose((t > 0), 2, 3));
    z = asils.pc.choose(isfinite(t), t, asils.pc.fmax((-(Inf)), x));
end
